def image_bytes(fmt="PNG", mode="RGB", size=(256, 128), orientation=None):
    image = Image.new(
        mode,
        size,
        128
        if mode == "L"
        else (80, 100, 120, 200)
        if mode == "RGBA"
        else (80, 100, 120),
    )
    out = BytesIO()
    kwargs = {}
    if orientation:
        exif = Image.Exif()
        exif[274] = orientation
        kwargs["exif"] = exif
    image.save(out, format=fmt, **kwargs)
    return out.getvalue()


@pytest.mark.parametrize(
    "fmt,mode",
    [
        ("JPEG", "RGB"),
        ("JPEG", "L"),
        ("PNG", "RGB"),
        ("PNG", "RGBA"),
        ("PNG", "L"),
        ("WEBP", "RGB"),
        ("WEBP", "RGBA"),
    ],
)
def test_IMG01_preprocessing_formats_modes_and_bounds(fmt, mode):
    prepared = PreprocessingService(
        Settings(_env_file=None, vision_max_side=128)
    ).prepare(image_bytes(fmt, mode))
    assert (prepared.original_width, prepared.original_height) == (256, 128)
    assert prepared.vision_image.shape == (64, 128, 3)
    evidence(
        f"IMG01-format-{fmt}-{mode}",
        {
            "scenario": "IMG-01",
            "format": fmt,
            "mode": mode,
            "original": [256, 128],
            "normalized": [128, 64],
            "scope": "generated image normalization; no camera/device or cat semantics",
        },
    )


@pytest.mark.parametrize(
    "orientation,expected",
    [(1, (256, 128)), (3, (256, 128)), (6, (128, 256)), (8, (128, 256))],
)
def test_IMG01_exif_orientation(orientation, expected):
    prepared = PreprocessingService(Settings(_env_file=None)).prepare(
        image_bytes("JPEG", orientation=orientation)
    )
    assert (prepared.original_width, prepared.original_height) == expected
    evidence(
        f"IMG01-exif-{orientation}",
        {
            "scenario": "IMG-01",
            "orientation": orientation,
            "normalized_original": expected,
        },
    )


@pytest.mark.parametrize(
    "defect",
    ["empty", "invalid", "truncated", "unsupported", "small", "pixels", "bytes"],
)
def test_IMG05_SEC06_invalid_image_matrix(defect):
    settings = Settings(_env_file=None, max_image_mb=1, max_image_pixels=256 * 128)
    data = {
        "empty": b"",
        "invalid": b"not an image",
        "truncated": image_bytes()[:30],
        "unsupported": image_bytes("BMP"),
        "small": image_bytes(size=(127, 128)),
        "pixels": image_bytes(size=(257, 128)),
        "bytes": b"x" * (1024 * 1024 + 1),
    }[defect]
    with pytest.raises(InvalidImageError):
        PreprocessingService(settings).prepare(data)
    positive = PreprocessingService(settings).prepare(image_bytes(size=(256, 128)))
    assert positive.original_width == 256
    evidence(
        "IMG05-invalid-" + defect,
        {
            "scenario": "IMG-05",
            "defect": defect,
            "rejected": True,
            "pixel_limit_positive_control": True,
        },
    )


def semantic():
    return GeminiCoatAnalysis.model_validate(
        {
            "validation": {
                "accepted": True,
                "reason": "ACCEPTED",
                "cat_count": 1,
                "quality": "GOOD",
                "message": "synthetic",
            },
            "coat_type": "Bicolor",
            "hair_type": "Curto",
            "color_assignments": [
                {"cluster_index": 0, "name": "Preto"},
                {"cluster_index": 1, "name": "Branco"},
            ],
            "confidence": 0.9,
            "pattern_map": {"base_color": "Preto", "pattern": "Bicolor"},
        }
    )


def configured(tmp_path, monkeypatch):
    service = AnalysisService(
        Settings(
            _env_file=None,
            analysis_cache_dir=str(tmp_path / "cache"),
            gemini_api_key="quality-canary-not-a-key-20261022",
        )
    )
    # Only transport, detection/mask, quality and color fixtures are fake. Real preprocessing/cache/schema/fusion remain.
    service.quality = SimpleNamespace(
        analyze=lambda image: SimpleNamespace(
            usable=True, width=image.shape[1], height=image.shape[0]
        )
    )
    service.segmentation = SimpleNamespace(
        segment_cat=lambda image: SegmentationResult(
            1,
            0.95,
            np.ones(image.shape[:2], dtype=np.uint8),
            (0, 0, image.shape[1], image.shape[0]),
            image,
        )
    )
    service.colors = SimpleNamespace(
        extract=lambda *args: [
            VisionColor(hex="#111111", percentage=60),
            VisionColor(hex="#EEEEEE", percentage=40),
        ]
    )
    monkeypatch.setattr(service, "_try_local_semantic_shortcut", lambda *args: None)
    monkeypatch.setattr(analysis_service, "_get_gemini_client", lambda key: object())
    return service


@pytest.mark.asyncio
async def test_IMG04_semantic_cache_hit_invalid_payload_and_missing_provider(
    tmp_path, monkeypatch
):
    service = configured(tmp_path, monkeypatch)
    calls = []

    def provider(*args):
        calls.append(1)
        return semantic()

    monkeypatch.setattr(service, "_analyze_with_gemini", provider)
    first = await service.analyze(cat_id="fixture", image_bytes=image_bytes())
    second = await service.analyze(cat_id="fixture", image_bytes=image_bytes())
    assert len(calls) == 1
    assert first.model_dump(exclude={"analyzed_at", "warnings"}) == second.model_dump(
        exclude={"analyzed_at", "warnings"}
    )
    with sqlite3.connect(service.semantic_cache.path) as db:
        db.execute("UPDATE semantic_results SET payload='invalid JSON'")
        db.commit()
    third = await service.analyze(cat_id="fixture", image_bytes=image_bytes())
    assert len(calls) == 2 and third.coat_type == first.coat_type
    service.settings.gemini_api_key = None
    # Valid cached semantics can be used without a provider key.
    cached = await service.analyze(cat_id="fixture", image_bytes=image_bytes())
    assert cached.colors == first.colors and len(calls) == 2
    with sqlite3.connect(service.semantic_cache.path) as db:
        db.execute("DELETE FROM semantic_results")
        db.commit()
    with pytest.raises(MissingApiKeyError):
        await service.analyze(cat_id="fixture", image_bytes=image_bytes())
    evidence(
        "IMG04-semantic-cache",
        {
            "scenario": "IMG-04",
            "provider_calls_for_four_analyses": 2,
            "valid_hit_without_key": True,
            "invalid_payload_refetched": True,
            "same_semantics_ignoring_timestamp_cache_warning": True,
            "missing_key_without_cache": "rejected",
            "scope": "fake model/provider; real SQLite/preprocessing/fusion; no segmentation inference",
        },
    )


@pytest.mark.parametrize("response", ["empty", "invalid-json", "invalid-schema"])
def test_RES05_provider_response_schema(response, tmp_path, monkeypatch):
    service = configured(tmp_path, monkeypatch)
    values = {
        "empty": SimpleNamespace(parsed=None, text=None),
        "invalid-json": SimpleNamespace(parsed=None, text="{"),
        "invalid-schema": SimpleNamespace(parsed={"unexpected": True}, text=None),
    }
    monkeypatch.setattr(
        service,
        "_generate_content_with_retry",
        lambda *args, **kwargs: values[response],
    )
    with pytest.raises(GeminiAnalysisError):
        service._analyze_with_gemini(b"synthetic", "image/jpeg", "context")
    evidence(
        "RES05-provider-" + response,
        {
            "scenario": "RES-05",
            "variant": response,
            "schema_failure_wrapped": True,
            "external_calls": 0,
        },
    )


@pytest.mark.parametrize(
    "status,retries,expected", [(503, 0, 1), (503, 1, 2), (429, 2, 3), (400, 2, 1)]
)
def test_RES05_provider_retry_boundaries(
    status, retries, expected, tmp_path, monkeypatch
):
    service = configured(tmp_path, monkeypatch)
    service.settings.gemini_max_retries = retries

    class Failure(Exception):
        status_code = status

    calls = []
    delays = []

    def generate(**kwargs):
        calls.append(1)
        raise Failure("controlled provider failure")

    monkeypatch.setattr(analysis_service, "sleep", delays.append)
    client = SimpleNamespace(models=SimpleNamespace(generate_content=generate))
    with pytest.raises(GeminiAnalysisError):
        service._generate_content_with_retry(client, contents=[], config=None)
    assert len(calls) == expected and len(delays) == expected - 1
    evidence(
        f"RES05-retry-{status}-{retries}",
        {
            "scenario": "RES-05",
            "status": status,
            "retry_setting": retries,
            "calls": len(calls),
            "backoff_seconds": delays,
            "external_calls": 0,
        },
    )


@pytest.mark.asyncio
async def test_SEC08_provider_error_canary_redaction_characterization(
    tmp_path, monkeypatch, caplog
):
    import logging

    service = configured(tmp_path, monkeypatch)
    canary = service.settings.gemini_api_key

    def failed(*args, **kwargs):
        raise RuntimeError("controlled upstream key=" + canary)

    monkeypatch.setattr(service, "_generate_content_with_retry", failed)
    with caplog.at_level(logging.ERROR, logger="app.services.analysis_service"):
        with pytest.raises(GeminiAnalysisError) as caught:
            service._analyze_with_gemini(b"image", "image/jpeg", "context")
    logs = "\n".join(
        r.getMessage() + (str(r.exc_info[1]) if r.exc_info else "")
        for r in caplog.records
        if r.name.startswith("app.")
    )
    assert canary not in str(caught.value)
    leaked = canary in logs
    import traceback

    leaked_trace = canary in "".join(traceback.format_exception(caught.value))
    evidence(
        "SEC08-provider-log-canary",
        {
            "scenario": "SEC-08",
            "wrapped_error_redacted": True,
            "raw_exception_log_contains_synthetic_key": leaked,
            "wrapped_trace_contains_synthetic_key": leaked_trace,
            "scope": "synthetic key and injected provider exception; no real credentials loaded or leaked",
            "finding": "logger.exception retains upstream raw exception despite redacted wrapped detail"
            if leaked
            else None,
        },
    )
    assert not leaked and not leaked_trace


def test_RES08_corrupt_private_cache_characterization(tmp_path):
    from app.services.analysis_cache import AnalysisCache

    cache = AnalysisCache(str(tmp_path / "own"))
    cache.set("fixture", "payload")
    cache.path.write_bytes(b"controlled corrupted SQLite")
    recovered = AnalysisCache(str(cache.path.parent))
    assert recovered.get("fixture") is None
    recovered.set("new", "payload")
    assert cache.path.read_bytes() == b"controlled corrupted SQLite"
    evidence(
        "RES08-corrupt-semantic-cache",
        {
            "scenario": "RES-08",
            "corrupted_cache": "optional cache bypassed without deleting raw file",
            "finding": None,
            "scope": "own derived cache only; authoritative user data is never reset",
        },
    )
